A=https://lead-recall-1.preview.emergentagent.com
T=$(curl -s -X POST $A/api/auth/login -H "Content-Type: application/json" -d '{"email":"admin@outreach.ai","password":"Admin@123"}' | python3 -c "import sys,json;print(json.load(sys.stdin)['token'])")
L=$(curl -s -X POST $A/api/leads -H "Authorization: Bearer $T" -H "Content-Type: application/json" -d '{"name":"Sarah Lin","company":"FlowDesk","platform":"linkedin","profile_url":"https://www.linkedin.com/in/sarahlin-flowdesk/","website":"https://flowdesk.io","bio":"Founder @ FlowDesk (B2B SaaS for agency project management). Posting weekly talking-head videos about building in public. Host of the Agency Ops podcast.","notes":"Her LinkedIn videos are raw webcam recordings with no captions, ~2 min long. Product demo on homepage is a silent screen recording.","followers":8400,"email":"sarah@flowdesk.io"}' | python3 -c "import sys,json;print(json.load(sys.stdin)['id'])")
echo "LEAD $L"
echo "--- dup test"; curl -s -X POST $A/api/leads -H "Authorization: Bearer $T" -H "Content-Type: application/json" -d '{"name":"Sarah L","platform":"linkedin","profile_url":"linkedin.com/in/sarahlin-flowdesk"}'; echo
echo "--- analyze"; timeout 200 curl -sN -X POST $A/api/leads/$L/analyze -H "Authorization: Bearer $T" | grep -v '^$' | cut -c1-600
echo "--- draft"; timeout 120 curl -sN -X POST $A/api/leads/$L/drafts/generate -H "Authorization: Bearer $T" -H "Content-Type: application/json" -d '{"type":"saas_ui_pitch","tone":"friendly","length":"short"}' | grep '"done"' | cut -c1-900
echo "--- reply"; timeout 120 curl -s -X POST $A/api/leads/$L/reply-explain -H "Authorization: Bearer $T" -H "Content-Type: application/json" -d '{"text":"Hey thanks! Interesting. What would something like that cost per month? We post 2 videos a week."}' | cut -c1-900
echo; echo "--- assistant"; timeout 150 curl -sN -X POST $A/api/assistant/chat -H "Authorization: Bearer $T" -H "Content-Type: application/json" -d '{"message":"How many leads do I have per stage? Then add a note to Sarah Lin saying: asked about monthly pricing."}' | grep -E '"ev"|"done"|error' | cut -c1-300
echo "--- dq"; timeout 120 curl -s -X POST $A/api/leads/$L/data-quality -H "Authorization: Bearer $T" | cut -c1-500
